from src.nodes.base import BaseNode
from src.runtime.assets.acquisition_online import get_project_asset_staging

class Hou_Mcp_Asset_Staging(BaseNode):
    name = "hou_mcp_asset_staging"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",      "string", widget_type="text", default="stats")
        self.add_input("project_id",  "string", widget_type="text")
        self.add_input("asset_id",    "string", widget_type="text")
        self.add_input("provider",    "string", widget_type="text", default="megascans")
        self.add_input("environment", "string", widget_type="text")
        self.add_input("top_k",       "int",    widget_type="int",  default=20)
        self.add_input("dry_run",     "bool",   widget_type="checkbox", default=False)
        self.add_output("entry",   "any")
        self.add_output("entries", "list")
        self.add_output("stats",   "any")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action      = str(inputs.get("action") or "stats").strip().lower()
        project_id  = str(inputs.get("project_id") or "").strip()
        asset_id    = str(inputs.get("asset_id") or "").strip()
        provider    = str(inputs.get("provider") or "megascans").strip()
        environment = str(inputs.get("environment") or "").strip()
        top_k       = int(inputs.get("top_k") or 20)
        dry_run     = bool(inputs.get("dry_run", False))
        try:
            staging = get_project_asset_staging()
            if action == "stage":
                e = staging.stage_asset(project_id, asset_id, provider=provider, environment=environment)
                return {"entry": e.to_dict(), "entries": [], "stats": staging.get_statistics(), "exec_out": True}
            elif action == "stage_environment":
                entries = staging.stage_environment(project_id, environment, top_k=top_k)
                return {"entry": {}, "entries": [e.to_dict() for e in entries], "stats": staging.get_statistics(), "exec_out": True}
            elif action == "build_cache":
                result = staging.build_project_cache(project_id)
                return {"entry": result, "entries": result.get("entries", []), "stats": staging.get_statistics(), "exec_out": True}
            elif action == "cleanup":
                result = staging.cleanup(project_id, dry_run=dry_run)
                return {"entry": result, "entries": [], "stats": staging.get_statistics(), "exec_out": True}
            elif action == "list":
                entries = [e.to_dict() for e in staging.get_project_assets(project_id)]
                return {"entry": {}, "entries": entries, "stats": staging.get_statistics(), "exec_out": True}
            else:
                return {"entry": {}, "entries": [], "stats": staging.get_statistics(), "exec_out": True}
        except Exception as e:
            self.log_error(f"hou_mcp_asset_staging failed: {e}")
            return {"entry": {}, "entries": [], "stats": {}, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Staging
